//! Summaries of a day, a week, a month or a year (`docs/spec/vault.md`, section 7).
//!
//! The person's AI writes them, as `summary` tasks answered with a `write_summary`
//! proposal the person accepts (decision 0010). A day is summarized from its events
//! and the files they link to; a longer period from the summaries inside it, never
//! from raw data. The `Events` section is generated by Ipse; the `Summary` text is the
//! AI's, then the person's: Ipse never writes over it without a proposal they accept.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use jiff::ToSpan;
use jiff::civil::{Date, Weekday};

use crate::search::SearchIndex;
use crate::vault::body::{Section, replace_section, section_text};
use crate::vault::{Common, FileType, Language, MemoryFile, Vault};
use crate::{Error, Result};

/// The length of a summary's period.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Period {
    /// One day.
    Day,
    /// One ISO week, Monday to Sunday.
    Week,
    /// One calendar month.
    Month,
    /// One calendar year.
    Year,
}

impl Period {
    /// `day`, `week`, `month` or `year`.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Day => "day",
            Self::Week => "week",
            Self::Month => "month",
            Self::Year => "year",
        }
    }

    /// Reads `day`, `week`, `month` or `year`.
    #[must_use]
    pub fn parse(text: &str) -> Option<Self> {
        [Self::Day, Self::Week, Self::Month, Self::Year]
            .into_iter()
            .find(|p| p.as_str() == text.trim())
    }

    /// The period just shorter, that this one is built from: `None` for a day.
    #[must_use]
    pub fn shorter(self) -> Option<Self> {
        match self {
            Self::Day => None,
            // Weeks straddle months: a month is built from its days.
            Self::Week | Self::Month => Some(Self::Day),
            Self::Year => Some(Self::Month),
        }
    }
}

/// One period: its length and its first day.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Span {
    /// Its length.
    pub period: Period,
    /// Its first day.
    pub start: Date,
}

impl Span {
    /// The period of `period` that holds `day`.
    #[must_use]
    pub fn holding(period: Period, day: Date) -> Self {
        let start = match period {
            Period::Day => day,
            Period::Week => {
                let back = i64::from(day.weekday().to_monday_zero_offset());
                day.checked_sub(back.days()).unwrap_or(day)
            }
            Period::Month => day.first_of_month(),
            Period::Year => day.first_of_year(),
        };
        Self { period, start }
    }

    /// The period of `period` starting on `start`, which must be its first day (a
    /// Monday for a week, the 1st for a month, January 1st for a year).
    ///
    /// # Errors
    ///
    /// [`Error::Refused`] when `start` is not a date or not the first day of a period.
    pub fn parse(period: &str, start: &str) -> Result<Self> {
        let period = Period::parse(period).ok_or_else(|| {
            Error::Refused("`period` must be day, week, month or year.".to_owned())
        })?;
        let date: Date = start
            .trim()
            .parse()
            .map_err(|_| Error::Refused("`start` must be a day, like 2026-11-14.".to_owned()))?;
        let span = Self::holding(period, date);
        if span.start != date {
            return Err(Error::Refused(format!(
                "`start` must be the first day of the {}: {}.",
                period.as_str(),
                span.start
            )));
        }
        Ok(span)
    }

    /// The day after its last day.
    #[must_use]
    pub fn end(&self) -> Date {
        let next = match self.period {
            Period::Day => self.start.checked_add(1.day()),
            Period::Week => self.start.checked_add(7.days()),
            Period::Month => self.start.checked_add(1.month()),
            Period::Year => self.start.checked_add(1.year()),
        };
        next.unwrap_or(self.start)
    }

    /// Its name: `2026-11-14`, `2026-W46`, `2026-11` or `2026`.
    #[must_use]
    pub fn label(&self) -> String {
        match self.period {
            Period::Day => self.start.to_string(),
            Period::Week => {
                let week = self.start.iso_week_date();
                format!("{:04}-W{:02}", week.year(), week.week())
            }
            Period::Month => self.start.strftime("%Y-%m").to_string(),
            Period::Year => format!("{:04}", self.start.year()),
        }
    }

    /// Its file, relative to the vault, with `/` (`docs/spec/vault.md`, section 1).
    #[must_use]
    pub fn file(&self) -> String {
        let label = self.label();
        match self.period {
            Period::Day | Period::Month => format!(
                "summaries/{}/{:04}/{label}.md",
                self.period.as_str(),
                self.start.year()
            ),
            Period::Week => format!(
                "summaries/week/{:04}/{label}.md",
                self.start.iso_week_date().year()
            ),
            Period::Year => format!("summaries/year/{label}.md"),
        }
    }

    /// `day:2026-11-14`: one key per period, to remember what was asked.
    #[must_use]
    pub fn key(&self) -> String {
        format!("{}:{}", self.period.as_str(), self.start)
    }

    /// Reads a key made by [`Span::key`].
    #[must_use]
    pub fn from_key(key: &str) -> Option<Self> {
        let (period, start) = key.split_once(':')?;
        Self::parse(period, start).ok()
    }

    /// The periods of `period` inside this one, in order. For a week or a month, its
    /// days; for a year, its months.
    #[must_use]
    pub fn parts(&self, period: Period) -> Vec<Self> {
        let mut parts = Vec::new();
        let mut at = self.start;
        let end = self.end();
        while at < end {
            let part = Self::holding(period, at);
            parts.push(part);
            let next = part.end();
            if next <= at {
                break;
            }
            at = next;
        }
        parts
    }
}

/// The event files of `span` in `index`, relative to the vault with `/`, by start.
#[must_use]
pub fn events_in(index: &SearchIndex, span: Span) -> Vec<String> {
    let end = span.end();
    index
        .events(
            |_| true,
            |e| {
                let day = e.start.date();
                day >= span.start && day < end
            },
        )
        .into_iter()
        .map(|e| slashed(e.path))
        .collect()
}

/// The event files of the days from `from` (included) to `to` (excluded) in `index`,
/// by day, relative to the vault with `/`: one pass over the events.
#[must_use]
pub fn events_by_day(index: &SearchIndex, from: Date, to: Date) -> BTreeMap<Date, Vec<String>> {
    let mut days: BTreeMap<Date, Vec<String>> = BTreeMap::new();
    for event in index.events(
        |_| true,
        |e| {
            let day = e.start.date();
            day >= from && day < to
        },
    ) {
        days.entry(event.start.date())
            .or_default()
            .push(slashed(event.path));
    }
    days
}

fn slashed(path: &Path) -> String {
    path.components()
        .map(|c| c.as_os_str().to_string_lossy())
        .collect::<Vec<_>>()
        .join("/")
}

/// The `Events` section of a summary: one link per event file.
fn events_list(events: &[String]) -> String {
    events
        .iter()
        .filter_map(|file| {
            let stem = file.rsplit('/').next()?.strip_suffix(".md")?;
            Some(format!("- [[{stem}]]"))
        })
        .collect::<Vec<_>>()
        .join("\n")
}

/// The `Summary` text of the summary at `path`, if the file exists and holds one.
#[must_use]
pub fn text_of(path: &Path) -> Option<String> {
    let file = MemoryFile::read(path).ok()?;
    section_text(file.body(), Section::Summary)
}

/// The summary of `span` with `text`, and `events` listed: a new file, or the one at
/// `path` with its `Summary` and `Events` sections replaced and everything else kept.
/// `source` goes in a new file's `sources`.
///
/// # Errors
///
/// [`Error::Invalid`] or [`Error::Io`] when the existing file cannot be read, or the
/// new one would not read back.
pub fn write_file(
    vault: &Vault,
    path: &Path,
    span: Span,
    text: &str,
    events: &[String],
    source: &str,
) -> Result<MemoryFile> {
    let language = vault.settings().language();
    let listed = events_list(events);
    if path.is_file() {
        let mut file = MemoryFile::read(path)?;
        let mut body = replace_section(file.body(), Section::Summary, text, language);
        if !listed.is_empty() || section_text(&body, Section::Events).is_some() {
            body = replace_section(&body, Section::Events, &listed, language);
        }
        file.set_body(body);
        return Ok(file);
    }
    let mut common = Common::new(FileType::Summary, vault.settings().time_zone())
        .ok_or_else(|| Error::Refused("A summary cannot be created.".to_owned()))?;
    common.sources = vec![source.to_owned()];
    let mut body = replace_section("", Section::Summary, text, language);
    if !listed.is_empty() {
        body = replace_section(&body, Section::Events, &listed, language);
    }
    let blank = MemoryFile::new(path, common, None, String::new()).render()?;
    // The period's keys are not among those Ipse types: they go before the closing line.
    let Some(closing) = blank[3..].find("\n---\n").map(|at| at + 4) else {
        return Err(Error::Refused("A summary cannot be created.".to_owned()));
    };
    let text = format!(
        "{}period: {}\nstart: {}\nend: {}\n{}{body}",
        &blank[..closing],
        span.period.as_str(),
        span.start,
        span.end(),
        &blank[closing..],
    );
    MemoryFile::parse(path, &text)
}

/// The path of `span`'s summary in the vault at `root`.
#[must_use]
pub fn path_of(root: &Path, span: Span) -> PathBuf {
    root.join(span.file())
}

/// Today in the vault's time zone.
#[must_use]
pub fn today(vault: &Vault) -> Date {
    jiff::Timestamp::now()
        .to_zoned(vault.settings().time_zone().clone())
        .date()
}

/// How a summary of `period` should read, for the person's AI: length, tone, an
/// example, in the vault's language.
#[must_use]
pub fn guidance(period: Period, language: Language) -> (String, String) {
    let (length, example) = match (period, language) {
        (Period::Day, Language::Fr) => (
            "2 à 4 phrases",
            "Déjeuner avec Marie au Café de la Gare : elle commence son nouveau poste lundi. Le soir, yoga au studio de la rue Paul-Bert, puis dîner chez Julie avec Marc.",
        ),
        (Period::Day, _) => (
            "2 to 4 sentences",
            "Lunch with Marie at the Station Café: she starts her new job on Monday. In the evening, yoga at the Paul-Bert studio, then dinner at Julie's with Marc.",
        ),
        (Period::Week, Language::Fr) => (
            "un paragraphe de 4 à 6 phrases",
            "Une semaine chargée au travail, avec la présentation de mercredi. Deux soirées de yoga, un dîner chez Julie, et un appel avec Léa pour préparer son anniversaire.",
        ),
        (Period::Week, _) => (
            "one paragraph of 4 to 6 sentences",
            "A busy week at work, with Wednesday's presentation. Two yoga evenings, a dinner at Julie's, and a call with Léa to plan her birthday.",
        ),
        (Period::Month, Language::Fr) => (
            "un ou deux paragraphes",
            "Novembre a tourné autour du nouveau projet et des retrouvailles avec la famille de Marc. Le yoga est devenu un rendez-vous de chaque semaine.",
        ),
        (Period::Month, _) => (
            "one or two paragraphs",
            "November revolved around the new project and seeing Marc's family again. Yoga became a weekly habit.",
        ),
        (Period::Year, Language::Fr) => (
            "deux à quatre paragraphes",
            "Une année de changements : un nouveau travail au printemps, un déménagement à Lyon en été, et beaucoup de temps avec Léa et Marc.",
        ),
        (Period::Year, _) => (
            "two to four paragraphs",
            "A year of change: a new job in the spring, a move to Lyon in the summer, and much time with Léa and Marc.",
        ),
    };
    let language_name = match language {
        Language::Fr => "French",
        _ => "English",
    };
    let built_from = match period {
        Period::Day => "the day's events and the people and places they link to",
        Period::Week | Period::Month => "the summaries of its days only",
        Period::Year => "the summaries of its months only",
    };
    let expected = format!(
        "Write the summary of this {period} in {language_name}, {length}, from {built_from}. \
         Write it as the person would in their own diary, without \"I\": who they saw, what they \
         did, what mattered, naming people and places as the items do. Say only what the items \
         say: no feelings or judgements they do not state, nothing about people's health or private \
         life unless the items say it plainly. Leave out routine with nothing to tell. Then answer \
         with one proposal: one `write_summary` change with this task's `period` and `start` and \
         your text, `task` set to this task's id, and a short reason. When an item is the current \
         summary, the person may have written it: keep their words and only add what the other \
         items bring.",
        period = period.as_str(),
    );
    (expected, example.to_owned())
}

/// Whether `day` is a Monday.
#[must_use]
pub fn is_monday(day: Date) -> bool {
    day.weekday() == Weekday::Monday
}

#[cfg(test)]
mod tests {
    use super::*;
    use jiff::civil::date;

    #[test]
    fn periods_and_their_files() {
        let day = Span::holding(Period::Day, date(2026, 11, 14));
        assert_eq!(day.file(), "summaries/day/2026/2026-11-14.md");
        assert_eq!(day.end(), date(2026, 11, 15));
        let week = Span::holding(Period::Week, date(2026, 11, 14));
        assert_eq!(week.start, date(2026, 11, 9), "the Monday");
        assert_eq!(week.file(), "summaries/week/2026/2026-W46.md");
        assert_eq!(week.parts(Period::Day).len(), 7);
        // The ISO year of a week can differ from its Monday's.
        let straddling = Span::holding(Period::Week, date(2026, 12, 31));
        assert_eq!(straddling.file(), "summaries/week/2026/2026-W53.md");
        let first = Span::holding(Period::Week, date(2027, 1, 4));
        assert_eq!(first.label(), "2027-W01");
        let month = Span::holding(Period::Month, date(2026, 11, 14));
        assert_eq!(month.file(), "summaries/month/2026/2026-11.md");
        assert_eq!(month.parts(Period::Day).len(), 30);
        let year = Span::holding(Period::Year, date(2026, 11, 14));
        assert_eq!(year.file(), "summaries/year/2026.md");
        assert_eq!(year.parts(Period::Month).len(), 12);
        assert_eq!(Span::from_key(&week.key()), Some(week));

        assert!(Span::parse("week", "2026-11-10").is_err(), "not a Monday");
        assert!(Span::parse("month", "2026-11-01").is_ok());
        assert!(Span::parse("decade", "2026-01-01").is_err());
        assert!(Span::parse("day", "14/11/2026").is_err());
    }
}
